def test_ownerless_resource_is_readable_by_any_user():
    user = {"id": 3, "role": "user"}
    resource = {"owner": None}
    assert is_authorized(user, resource) is True


def test_default_denies_when_role_missing_owner_mismatch():
    user = {"id": 4, "role": "user"}
    resource = {"owner": 5}
    assert is_authorized(user, resource) is False
