# test_authz.py
from authz import is_authorized


def test_admin_authorized_for_any_resource():
    admin = {"id": 1, "role": "admin"}
    assert is_authorized(admin, {"owner": 2}) is True
    assert is_authorized(admin, {"owner": None}) is True


def test_owner_authorized_for_own_resource():
    user = {"id": 1, "role": "user"}
    assert is_authorized(user, {"owner": 1}) is True


def test_non_owner_denied():
    user = {"id": 1, "role": "user"}
    assert is_authorized(user, {"owner": 2}) is False


def test_unowned_resource_readable_by_any_user():
    user = {"id": 1, "role": "user"}
    assert is_authorized(user, {"owner": None}) is True
```

Points and decisions:

1. **is_authorized() falls open because the last line is `return True`; default should deny.** — ACCEPT. This is a genuine security bug: the function authorizes everyone for everything, and flipping the default to deny is the correct fix.
2. **Replace your file with the reviewer's corrected version.** — DECLINE. The proposed replacement introduces a new problem: `resource.get("owner") in (user["id"], None)` authorizes any user whenever the resource has no `owner` key (or has `owner=None`), which is another fail-open path; I'll fix the default-deny bug without that change.

